/** Generated by scaffold-crud-pages. Query hooks for Chapters.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchChaptersList,
  fetchChaptersById,
  createChapters,
  updateChapters,
  deleteChapters,
  type FetchChaptersListParams,
} from '~/services/httpServices/chaptersService';
import type { CreateChaptersRequest, UpdateChaptersRequest } from '~/types/chapters';

const DOMAIN = 'chapters';

export function useChaptersList(params?: FetchChaptersListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchChaptersList(params),
  });
}

export function useChapters(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchChaptersById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateChapters() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateChaptersRequest) => createChapters(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateChapters() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateChaptersRequest }) =>
      updateChapters(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteChapters() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteChapters(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
